INSERT INTO landing_pages (slug, label, is_published, cta_region_slug, image_url, image_alt, sort_order, h1_en, intro_en, content_en, meta_title_en, meta_description_en, h1_tr, intro_tr, content_tr, meta_title_tr, meta_description_tr, h1_de, intro_de, content_de, meta_title_de, meta_description_de, h1_pl, intro_pl, content_pl, meta_title_pl, meta_description_pl, h1_ru, intro_ru, content_ru, meta_title_ru, meta_description_ru, h1_nl, intro_nl, content_nl, meta_title_nl, meta_description_nl, h1_ro, intro_ro, content_ro, meta_title_ro, meta_description_ro)
SELECT 'vip-transfer-antalya', 'VIP Transfer Antalya', true, NULL, 'C:/Program Files/Git/images/havaalani-vip-transfer.jpg', 'VIP transfer vehicle at Antalya Airport', 102, 'VIP Transfer Antalya Airport', 'The premium tier of TORVIAN''s fleet — newer vehicles, English-speaking drivers, and a meet & greet built for guests who don''t want to wait in line.', '<p>"VIP transfer" means more than a private car: it''s the top-spec vehicle in our fleet, a driver assigned to you alone from the moment you land, and a pickup that starts the second you clear the arrivals hall — not ten minutes later while a shared shuttle fills up. It costs the same as our standard private transfer; the difference is entirely in the experience.</p><p>VIP is TORVIAN''s standard — every booking includes it at no extra charge. There is no separate "economy" tier to upsell you out of.</p><h2>What You Get With Every VIP Booking</h2><ul><li>Newest Mercedes Vito in the fleet — leather interior, no worn seats</li><li>Driver assigned to you only — never shared with another booking</li><li>English-speaking driver as standard; German or Russian on request</li><li>Priority meet &amp; greet: your name board is at the front of the arrivals hall</li><li>Bottled water and phone charging cable on board</li><li>Free Wi-Fi and climate control set before you board</li><li>Same fixed price as standard transfer — VIP is a service tier, not a surcharge</li><li>Covers every resort area on the coast, from Kundu-Lara to Alanya</li></ul><h2>The VIP Vehicle</h2><ul><li>Up to 5 passengers, one group per car</li><li>Free on-board Wi-Fi</li><li>Climate control, pre-set for arrival</li><li>Newest vehicles in the fleet</li></ul><h2>VIP Transfer Available To</h2><ul><li><a href="/belek-transfer">VIP Transfer to Belek</a></li><li><a href="/side-transfer">VIP Transfer to Side</a></li><li><a href="/alanya-transfer">VIP Transfer to Alanya</a></li><li><a href="/kemer-transfer">VIP Transfer to Kemer</a></li><li><a href="/kundu-lara-transfer">VIP Transfer to Kundu-Lara</a></li><li><a href="/sehirici-transfer">VIP Transfer to Antalya City</a></li></ul><h2>Frequently Asked Questions</h2><h3>What actually makes this a "VIP" transfer?</h3><p>Three things: the vehicle is the newest Mercedes Vito in our fleet, the driver is assigned to you alone from landing to drop-off (no shared stops, ever), and your meet &amp; greet is prioritized at the front of the arrivals hall rather than a general waiting area.</p><h3>Does VIP transfer cost more than a standard private transfer?</h3><p>No. At TORVIAN, VIP is our standard service level, not a paid upgrade — every booking already includes the private vehicle, meet &amp; greet, and flight tracking described here at the same fixed price shown at checkout.</p><h3>Can I request an English- or German-speaking driver?</h3><p>Yes. All drivers speak basic English. If you''d prefer a German- or Russian-speaking driver specifically, add a note when booking and we''ll confirm availability before your pickup.</p><h3>Which vehicle is used for the VIP service?</h3><p>A Mercedes Vito with leather seats, air conditioning, and free Wi-Fi, seating up to 5 passengers with generous luggage space. It''s the same model across our fleet — VIP bookings get the newest unit available on your travel date.</p><h3>Does VIP transfer cover every resort area, or only specific hotels?</h3><p>Every resort area on the Turkish Riviera that we serve — from Kundu-Lara nearest the airport to Alanya at the far east of the coast. Choose your destination during booking and the same VIP standard applies regardless of distance.</p>', 'VIP Transfer Antalya Airport | Premium Private Car Service', 'VIP transfer from Antalya Airport: newer Mercedes Vito fleet, English-speaking drivers, priority meet & greet. Fixed price, no shared stops. Book online in 2 minutes.', 'Antalya Havalimanı VIP Transfer', 'TORVIAN filosunun premium katmanı — en yeni araçlar, deneyimli şoförler ve varış salonunda beklemeden başlayan karşılama.', '<p>"VIP transfer" sadece özel araç demek değildir: filomuzdaki en üst seviye araç, indiğiniz andan itibaren yalnızca size ayrılan bir şoför ve paylaşımlı bir servisin dolmasını beklemeden, varış salonundan çıkar çıkmaz başlayan bir karşılama demektir. Fiyatı standart özel transferimizle aynıdır; fark tamamen deneyimdedir.</p><p>VIP, TORVIAN''ın standardıdır — her rezervasyona ek ücret olmadan dahildir. Sizi yukarı satmak için ayrı bir "ekonomi" katmanı yoktur.</p><h2>Her VIP Rezervasyonda Neler Dahil</h2><ul><li>Filodaki en yeni Mercedes Vito — deri koltuk, yıpranmamış iç mekan</li><li>Yalnızca size ayrılan şoför — başka bir rezervasyonla paylaşılmaz</li><li>Standart olarak İngilizce konuşan şoför; talep üzerine Almanca veya Rusça</li><li>Öncelikli karşılama: isim tabelanız varış salonunun en önünde</li><li>Araçta su ve telefon şarj kablosu</li><li>Binmeden önce ayarlanmış ücretsiz Wi-Fi ve klima</li><li>Standart transferle aynı sabit fiyat — VIP bir hizmet seviyesidir, ek ücret değil</li><li>Kundu-Lara''dan Alanya''ya kadar sahildeki tüm tatil bölgelerini kapsar</li></ul><h2>VIP Aracınız</h2><ul><li>5 yolcuya kadar, araç başına tek grup</li><li>Ücretsiz araç içi Wi-Fi</li><li>Varışa göre önceden ayarlanmış klima</li><li>Filodaki en yeni araçlar</li></ul><h2>VIP Transfer Hizmeti Verilen Bölgeler</h2><ul><li><a href="/belek-transfer">Belek VIP Transfer</a></li><li><a href="/side-transfer">Side VIP Transfer</a></li><li><a href="/alanya-transfer">Alanya VIP Transfer</a></li><li><a href="/kemer-transfer">Kemer VIP Transfer</a></li><li><a href="/kundu-lara-transfer">Kundu-Lara VIP Transfer</a></li><li><a href="/sehirici-transfer">Antalya Şehir Merkezi VIP Transfer</a></li></ul><h2>Sık Sorulan Sorular</h2><h3>Bu transferi "VIP" yapan tam olarak nedir?</h3><p>Üç şey: araç filomuzdaki en yeni Mercedes Vito''dur, şoför inişinizden bırakışınıza kadar yalnızca size ayrılır (asla paylaşımlı durak yapılmaz) ve karşılamanız varış salonunun genel bekleme alanı yerine en önde önceliklidir.</p><h3>VIP transfer standart özel transferden daha mı pahalı?</h3><p>Hayır. TORVIAN''da VIP, ücretli bir yükseltme değil standart hizmet seviyemizdir — her rezervasyon zaten burada anlatılan özel araç, karşılama ve uçuş takibini ödeme sırasında görülen sabit fiyatla içerir.</p><h3>İngilizce veya Almanca konuşan bir şoför talep edebilir miyim?</h3><p>Evet. Tüm şoförlerimiz temel İngilizce konuşur. Özellikle Almanca veya Rusça konuşan bir şoför tercih ediyorsanız, rezervasyon sırasında not bırakın; karşılamadan önce müsaitliği onaylarız.</p><h3>VIP hizmette hangi araç kullanılıyor?</h3><p>Deri koltuklu, klimalı ve ücretsiz Wi-Fi''lı, 5 yolcuya kadar kapasiteli ve geniş bagaj alanına sahip bir Mercedes Vito. Filomuzdaki tüm araçlar aynı modeldir — VIP rezervasyonlar seyahat tarihinizde müsait en yeni aracı alır.</p><h3>VIP transfer her tatil bölgesini mi kapsıyor, yoksa sadece belirli otelleri mi?</h3><p>Hizmet verdiğimiz Türk Rivierası''ndaki her tatil bölgesini kapsar — havalimanına en yakın Kundu-Lara''dan sahilin doğusundaki Alanya''ya kadar. Rezervasyon sırasında varış noktanızı seçin, mesafeden bağımsız olarak aynı VIP standardı uygulanır.</p>', 'Antalya Havalimanı VIP Transfer | Özel Şoförlü Premium Araç', 'Antalya Havalimanı''ndan VIP transfer: filodaki en yeni Mercedes Vito, öncelikli karşılama, sadece size ayrılmış şoför. Sabit fiyat, paylaşımlı durak yok. 2 dakikada rezervasyon.', 'VIP Transfer Antalya Flughafen', 'Die Premiumstufe der TORVIAN-Flotte — neuere Fahrzeuge, Ihnen allein zugewiesene Fahrer und ein Empfang, der beginnt, sobald Sie die Ankunftshalle verlassen.', '<p>"VIP Transfer" bedeutet mehr als ein Privatfahrzeug: Es ist das hochwertigste Fahrzeug unserer Flotte, ein Fahrer, der ab der Landung ausschließlich Ihnen zugeteilt ist, und eine Abholung, die beginnt, sobald Sie die Ankunftshalle verlassen — nicht erst zehn Minuten später, während ein Sammelshuttle sich füllt. Der Preis ist derselbe wie bei unserem Standard-Privattransfer; der Unterschied liegt ganz im Erlebnis.</p><p>VIP ist der Standard bei TORVIAN — in jeder Buchung ohne Aufpreis enthalten. Es gibt keine separate "Economy"-Stufe, aus der wir Sie hochverkaufen.</p><h2>Das Erhalten Sie Bei Jeder VIP-Buchung</h2><ul><li>Neuester Mercedes Vito der Flotte — Ledersitze, keine abgenutzte Ausstattung</li><li>Fahrer nur für Sie — nie mit einer anderen Buchung geteilt</li><li>Englischsprachiger Fahrer als Standard; Deutsch oder Russisch auf Anfrage</li><li>Priorisiertes Meet &amp; Greet: Ihr Namensschild steht vorne in der Ankunftshalle</li><li>Wasser und Ladekabel fürs Telefon an Bord</li><li>Kostenloses WLAN und Klimaanlage, vor Ihrer Ankunft eingestellt</li><li>Gleicher Festpreis wie beim Standardtransfer — VIP ist eine Servicestufe, kein Aufpreis</li><li>Deckt jedes Ferienort an der Küste ab, von Kundu-Lara bis Alanya</li></ul><h2>Ihr VIP-Fahrzeug</h2><ul><li>Bis zu 5 Passagiere, eine Gruppe pro Fahrzeug</li><li>Kostenloses WLAN an Bord</li><li>Klimaanlage, vor Ankunft eingestellt</li><li>Neueste Fahrzeuge der Flotte</li></ul><h2>VIP Transfer Verfügbar Nach</h2><ul><li><a href="/belek-transfer">VIP Transfer nach Belek</a></li><li><a href="/side-transfer">VIP Transfer nach Side</a></li><li><a href="/alanya-transfer">VIP Transfer nach Alanya</a></li><li><a href="/kemer-transfer">VIP Transfer nach Kemer</a></li><li><a href="/kundu-lara-transfer">VIP Transfer nach Kundu-Lara</a></li><li><a href="/sehirici-transfer">VIP Transfer Antalya Stadtzentrum</a></li></ul><h2>Häufig gestellte Fragen</h2><h3>Was macht diesen Transfer wirklich zu "VIP"?</h3><p>Drei Dinge: Das Fahrzeug ist der neueste Mercedes Vito unserer Flotte, der Fahrer ist ab der Landung bis zum Ziel ausschließlich Ihnen zugeteilt (nie Sammelstopps), und Ihr Meet &amp; Greet hat Priorität vorne in der Ankunftshalle statt in einem allgemeinen Wartebereich.</p><h3>Kostet der VIP-Transfer mehr als ein normaler Privattransfer?</h3><p>Nein. Bei TORVIAN ist VIP unser Standard-Servicelevel, kein kostenpflichtiges Upgrade — jede Buchung enthält bereits das hier beschriebene Privatfahrzeug, Meet &amp; Greet und die Flugverfolgung zum selben Festpreis, der beim Bezahlen angezeigt wird.</p><h3>Kann ich einen englisch- oder deutschsprachigen Fahrer anfragen?</h3><p>Ja. Alle Fahrer sprechen grundlegendes Englisch. Wenn Sie speziell einen deutsch- oder russischsprachigen Fahrer wünschen, hinterlassen Sie bei der Buchung eine Notiz — wir bestätigen die Verfügbarkeit vor Ihrer Abholung.</p><h3>Welches Fahrzeug wird für den VIP-Service eingesetzt?</h3><p>Ein Mercedes Vito mit Ledersitzen, Klimaanlage und kostenlosem WLAN, mit Platz für bis zu 5 Passagiere und großzügigem Gepäckraum. Es ist dasselbe Modell in unserer gesamten Flotte — VIP-Buchungen erhalten das neueste verfügbare Fahrzeug an Ihrem Reisedatum.</p><h3>Deckt der VIP-Transfer jedes Ferienort ab oder nur bestimmte Hotels?</h3><p>Jedes Ferienort an der Türkischen Riviera, das wir bedienen — von Kundu-Lara, dem Flughafen am nächsten, bis Alanya im Osten der Küste. Wählen Sie Ihr Ziel bei der Buchung; derselbe VIP-Standard gilt unabhängig von der Entfernung.</p>', 'VIP Transfer Antalya Flughafen | Premium Privatfahrzeug', 'VIP Transfer ab Flughafen Antalya: neuester Mercedes Vito der Flotte, Ihnen allein zugewiesener Fahrer, priorisiertes Meet & Greet. Festpreis, keine Sammelstopps. In 2 Minuten buchen.', 'VIP Transfer Antalya Lotnisko', 'Premium warstwa floty TORVIAN — nowsze pojazdy, kierowca przypisany tylko Tobie i powitanie, które zaczyna się, gdy tylko opuścisz halę przylotów.', '<p>"VIP transfer" to więcej niż prywatny pojazd: to najlepszy pojazd w naszej flocie, kierowca przypisany wyłącznie Tobie od momentu lądowania i odbiór, który zaczyna się natychmiast po opuszczeniu hali przylotów — a nie dziesięć minut później, gdy zapełnia się wspólny bus. Cena jest taka sama jak przy standardowym transferze prywatnym; różnica leży całkowicie w doświadczeniu.</p><p>VIP to standard TORVIAN — zawarty w każdej rezerwacji bez dodatkowej opłaty. Nie ma osobnego poziomu "ekonomicznego", z którego chcielibyśmy Cię namówić na droższą opcję.</p><h2>Co Otrzymujesz Przy Każdej Rezerwacji VIP</h2><ul><li>Najnowszy Mercedes Vito we flocie — skórzane fotele, brak zużytego wnętrza</li><li>Kierowca przypisany tylko Tobie — nigdy dzielony z inną rezerwacją</li><li>Kierowca mówiący po angielsku standardowo; niemiecki lub rosyjski na życzenie</li><li>Priorytetowe powitanie: Twoja tabliczka jest na przedzie hali przylotów</li><li>Woda i kabel do ładowania telefonu na pokładzie</li><li>Bezpłatne Wi-Fi i klimatyzacja ustawione przed Twoim przybyciem</li><li>Ta sama stała cena co przy standardowym transferze — VIP to poziom usługi, nie dopłata</li><li>Obejmuje każdy kurort na wybrzeżu, od Kundu-Lara po Alanyę</li></ul><h2>Twój Pojazd VIP</h2><ul><li>Do 5 pasażerów, jedna grupa na pojazd</li><li>Bezpłatne Wi-Fi na pokładzie</li><li>Klimatyzacja ustawiona przed przybyciem</li><li>Najnowsze pojazdy floty</li></ul><h2>Transfer VIP Dostępny Do</h2><ul><li><a href="/belek-transfer">VIP Transfer do Belek</a></li><li><a href="/side-transfer">VIP Transfer do Side</a></li><li><a href="/alanya-transfer">VIP Transfer do Alanyi</a></li><li><a href="/kemer-transfer">VIP Transfer do Kemer</a></li><li><a href="/kundu-lara-transfer">VIP Transfer do Kundu-Lara</a></li><li><a href="/sehirici-transfer">VIP Transfer do Centrum Antalyi</a></li></ul><h2>Najczęściej zadawane pytania</h2><h3>Co dokładnie czyni ten transfer "VIP"?</h3><p>Trzy rzeczy: pojazd to najnowszy Mercedes Vito w naszej flocie, kierowca jest przypisany wyłącznie Tobie od lądowania do celu (nigdy wspólne przystanki), a Twoje powitanie ma priorytet na przedzie hali przylotów zamiast w ogólnej strefie oczekiwania.</p><h3>Czy transfer VIP kosztuje więcej niż standardowy transfer prywatny?</h3><p>Nie. W TORVIAN VIP to nasz standardowy poziom usługi, a nie płatne ulepszenie — każda rezerwacja już zawiera opisany tu prywatny pojazd, powitanie i śledzenie lotu w tej samej stałej cenie widocznej przy płatności.</p><h3>Czy mogę poprosić o kierowcę mówiącego po angielsku lub niemiecku?</h3><p>Tak. Wszyscy kierowcy mówią podstawowym angielskim. Jeśli wolisz konkretnie kierowcę mówiącego po niemiecku lub rosyjsku, zostaw notatkę podczas rezerwacji — potwierdzimy dostępność przed odbiorem.</p><h3>Jaki pojazd jest używany w usłudze VIP?</h3><p>Mercedes Vito ze skórzanymi fotelami, klimatyzacją i bezpłatnym Wi-Fi, mieszczący do 5 pasażerów z dużą przestrzenią na bagaż. To ten sam model w całej naszej flocie — rezerwacje VIP otrzymują najnowszy dostępny pojazd w dniu podróży.</p><h3>Czy transfer VIP obejmuje każdy kurort, czy tylko określone hotele?</h3><p>Każdy kurort na Riwierze Tureckiej, który obsługujemy — od Kundu-Lara najbliżej lotniska po Alanyę na wschodnim krańcu wybrzeża. Wybierz cel podczas rezerwacji; ten sam standard VIP obowiązuje niezależnie od odległości.</p>', 'VIP Transfer Antalya Lotnisko | Prywatny Pojazd Premium', 'VIP transfer z lotniska Antalya: najnowszy Mercedes Vito z floty, kierowca przypisany tylko Tobie, priorytetowe powitanie. Stała cena, bez wspólnych przystanków. Rezerwacja w 2 minuty.', 'VIP Трансфер Аэропорт Анталии', 'Премиальный уровень парка TORVIAN — новые автомобили, водитель только для вас и встреча, которая начинается сразу у выхода из зала прилёта.', '<p>«VIP-трансфер» — это больше, чем просто частный автомобиль: это лучший автомобиль нашего парка, водитель, закреплённый исключительно за вами с момента приземления, и подача, которая начинается сразу после выхода из зала прилёта — а не через десять минут, пока заполняется групповой шаттл. Цена такая же, как у стандартного частного трансфера; разница целиком в качестве обслуживания.</p><p>VIP — это стандарт TORVIAN, включённый в каждое бронирование без доплаты. Отдельного «эконом»-уровня, из которого вас пытались бы поднять до VIP, у нас нет.</p><h2>Что Входит в Каждое VIP-Бронирование</h2><ul><li>Новейший Mercedes Vito в парке — кожаный салон, без изношенной отделки</li><li>Водитель только для вас — никогда не делится с другим бронированием</li><li>Водитель, говорящий по-английски, по умолчанию; немецкий или русский по запросу</li><li>Приоритетная встреча: табличка с вашим именем — в первых рядах зала прилёта</li><li>Вода и кабель для зарядки телефона в салоне</li><li>Бесплатный Wi-Fi и кондиционер, настроенные заранее</li><li>Та же фиксированная цена, что и у стандартного трансфера — VIP это уровень сервиса, а не доплата</li><li>Покрывает все курортные зоны побережья, от Кунду-Лары до Аланьи</li></ul><h2>Ваш VIP-Автомобиль</h2><ul><li>До 5 пассажиров, одна группа на автомобиль</li><li>Бесплатный Wi-Fi в салоне</li><li>Кондиционер, настроенный заранее</li><li>Новейшие автомобили парка</li></ul><h2>VIP Трансфер Доступен В</h2><ul><li><a href="/belek-transfer">VIP трансфер в Белек</a></li><li><a href="/side-transfer">VIP трансфер в Сиде</a></li><li><a href="/alanya-transfer">VIP трансфер в Аланью</a></li><li><a href="/kemer-transfer">VIP трансфер в Кемер</a></li><li><a href="/kundu-lara-transfer">VIP трансфер в Кунду-Лару</a></li><li><a href="/sehirici-transfer">VIP трансфер в центр Анталии</a></li></ul><h2>Часто задаваемые вопросы</h2><h3>Что именно делает этот трансфер «VIP»?</h3><p>Три вещи: автомобиль — новейший Mercedes Vito нашего парка, водитель закреплён исключительно за вами с момента приземления до высадки (никогда никаких общих остановок), а ваша встреча приоритетна — в первых рядах зала прилёта, а не в общей зоне ожидания.</p><h3>VIP-трансфер стоит дороже стандартного частного трансфера?</h3><p>Нет. В TORVIAN VIP — это наш стандартный уровень сервиса, а не платное улучшение: каждое бронирование уже включает описанный здесь частный автомобиль, встречу и отслеживание рейса по той же фиксированной цене, которая показана при оформлении.</p><h3>Могу ли я попросить водителя, говорящего по-английски или по-немецки?</h3><p>Да. Все водители говорят на базовом английском. Если вы предпочитаете именно немецко- или русскоговорящего водителя, оставьте заметку при бронировании — мы подтвердим доступность до вашей встречи.</p><h3>Какой автомобиль используется для VIP-сервиса?</h3><p>Mercedes Vito с кожаными сиденьями, кондиционером и бесплатным Wi-Fi, вмещающий до 5 пассажиров с просторным багажным отделением. Это одна и та же модель во всём нашем парке — VIP-бронирования получают новейший доступный автомобиль на дату вашей поездки.</p><h3>VIP-трансфер покрывает все курортные зоны или только определённые отели?</h3><p>Все курортные зоны Турецкой Ривьеры, которые мы обслуживаем — от Кунду-Лары, ближайшей к аэропорту, до Аланьи на восточном краю побережья. Выберите пункт назначения при бронировании — тот же стандарт VIP действует независимо от расстояния.</p>', 'VIP Трансфер Аэропорт Анталии | Премиальный Частный Автомобиль', 'VIP-трансфер из аэропорта Анталии: новейший Mercedes Vito в парке, водитель закреплён только за вами, приоритетная встреча. Фиксированная цена, без общих остановок. Бронирование за 2 минуты.', 'VIP Transfer Antalya Luchthaven', 'De premium laag van de TORVIAN-vloot — nieuwere voertuigen, een chauffeur alleen voor u, en een ontvangst die begint zodra u de aankomsthal verlaat.', '<p>"VIP-transfer" betekent meer dan een privévoertuig: het is het beste voertuig uit onze vloot, een chauffeur die vanaf de landing uitsluitend aan u is toegewezen, en een ophaalservice die begint zodra u de aankomsthal verlaat — niet tien minuten later terwijl een gedeelde shuttle zich vult. De prijs is hetzelfde als bij onze standaard privétransfer; het verschil zit volledig in de ervaring.</p><p>VIP is de standaard bij TORVIAN — inbegrepen bij elke boeking zonder toeslag. Er is geen apart "economy"-niveau waar wij u vanaf proberen te verkopen.</p><h2>Wat U Krijgt Bij Elke VIP-Boeking</h2><ul><li>Nieuwste Mercedes Vito uit de vloot — leren bekleding, geen versleten interieur</li><li>Chauffeur alleen voor u — nooit gedeeld met een andere boeking</li><li>Engelssprekende chauffeur als standaard; Duits of Russisch op aanvraag</li><li>Prioritaire ontvangst: uw naambord staat vooraan in de aankomsthal</li><li>Water en telefoonoplaadkabel aan boord</li><li>Gratis wifi en airco, vooraf ingesteld voor uw aankomst</li><li>Dezelfde vaste prijs als de standaardtransfer — VIP is een serviceniveau, geen toeslag</li><li>Dekt elk resortgebied aan de kust, van Kundu-Lara tot Alanya</li></ul><h2>Uw VIP-Voertuig</h2><ul><li>Tot 5 passagiers, één groep per voertuig</li><li>Gratis wifi aan boord</li><li>Airco, vooraf ingesteld voor aankomst</li><li>Nieuwste voertuigen van de vloot</li></ul><h2>VIP-Transfer Beschikbaar Naar</h2><ul><li><a href="/belek-transfer">VIP-transfer naar Belek</a></li><li><a href="/side-transfer">VIP-transfer naar Side</a></li><li><a href="/alanya-transfer">VIP-transfer naar Alanya</a></li><li><a href="/kemer-transfer">VIP-transfer naar Kemer</a></li><li><a href="/kundu-lara-transfer">VIP-transfer naar Kundu-Lara</a></li><li><a href="/sehirici-transfer">VIP-transfer naar Antalya centrum</a></li></ul><h2>Veelgestelde vragen</h2><h3>Wat maakt deze transfer echt "VIP"?</h3><p>Drie dingen: het voertuig is de nieuwste Mercedes Vito uit onze vloot, de chauffeur is vanaf de landing tot aan afzetten uitsluitend aan u toegewezen (nooit gedeelde stops), en uw ontvangst heeft prioriteit vooraan in de aankomsthal in plaats van een algemene wachtruimte.</p><h3>Kost een VIP-transfer meer dan een standaard privétransfer?</h3><p>Nee. Bij TORVIAN is VIP ons standaard serviceniveau, geen betaalde upgrade — elke boeking bevat al het hier beschreven privévoertuig, de ontvangst en vluchtmonitoring voor dezelfde vaste prijs die u bij het afrekenen ziet.</p><h3>Kan ik een Engels- of Duitssprekende chauffeur aanvragen?</h3><p>Ja. Alle chauffeurs spreken basis Engels. Wilt u specifiek een Duits- of Russischsprekende chauffeur, vermeld dit dan bij het boeken — wij bevestigen de beschikbaarheid vóór uw ophaalmoment.</p><h3>Welk voertuig wordt gebruikt voor de VIP-service?</h3><p>Een Mercedes Vito met leren stoelen, airconditioning en gratis wifi, met plaats voor maximaal 5 passagiers en ruime bagageruimte. Het is hetzelfde model in onze hele vloot — VIP-boekingen krijgen het nieuwste beschikbare voertuig op uw reisdatum.</p><h3>Dekt de VIP-transfer elk resortgebied, of alleen bepaalde hotels?</h3><p>Elk resortgebied aan de Turkse Rivièra dat wij bedienen — van Kundu-Lara, het dichtst bij de luchthaven, tot Alanya aan het oostelijke uiteinde van de kust. Kies uw bestemming tijdens het boeken; dezelfde VIP-standaard geldt ongeacht de afstand.</p>', 'VIP Transfer Antalya Luchthaven | Premium Privévoertuig', 'VIP-transfer vanaf de luchthaven Antalya: nieuwste Mercedes Vito uit de vloot, chauffeur alleen voor u, prioritaire ontvangst. Vaste prijs, geen gedeelde stops. Boek online in 2 minuten.', 'Transfer VIP Aeroportul Antalya', 'Nivelul premium al flotei TORVIAN — vehicule mai noi, un șofer numai pentru tine și o întâmpinare care începe din clipa în care ieși în holul de sosiri.', '<p>„Transfer VIP” înseamnă mai mult decât un vehicul privat: este cel mai bun vehicul din flota noastră, un șofer alocat exclusiv ție din momentul aterizării și o preluare care începe imediat ce ieși în holul de sosiri — nu zece minute mai târziu, în timp ce o navetă comună se umple. Prețul este același ca la transferul nostru privat standard; diferența stă în întregime în experiență.</p><p>VIP este standardul la TORVIAN — inclus în fiecare rezervare, fără supliment. Nu există un nivel „economy” separat de la care să încercăm să te urcăm.</p><h2>Ce primești la fiecare rezervare VIP</h2><ul><li>Cel mai nou Mercedes Vito din flotă — tapițerie din piele, fără interior uzat</li><li>Șofer numai pentru tine — niciodată împărțit cu altă rezervare</li><li>Șofer vorbitor de engleză ca standard; germană sau rusă la cerere</li><li>Întâmpinare prioritară: panoul cu numele tău este în față, în holul de sosiri</li><li>Apă și cablu de încărcare pentru telefon la bord</li><li>Wi-Fi gratuit și aer condiționat, pornit înainte de sosirea ta</li><li>Același preț fix ca transferul standard — VIP este un nivel de serviciu, nu un supliment</li><li>Acoperă orice zonă de stațiune de pe coastă, de la Kundu-Lara până la Alanya</li></ul><h2>Vehiculul tău VIP</h2><ul><li>Până la 5 pasageri, un singur grup per vehicul</li><li>Wi-Fi gratuit la bord</li><li>Aer condiționat, pornit înainte de sosire</li><li>Cele mai noi vehicule din flotă</li></ul><h2>Transfer VIP disponibil către</h2><ul><li><a href="/belek-transfer">Transfer VIP către Belek</a></li><li><a href="/side-transfer">Transfer VIP către Side</a></li><li><a href="/alanya-transfer">Transfer VIP către Alanya</a></li><li><a href="/kemer-transfer">Transfer VIP către Kemer</a></li><li><a href="/kundu-lara-transfer">Transfer VIP către Kundu-Lara</a></li><li><a href="/sehirici-transfer">Transfer VIP către centrul Antalyei</a></li></ul><h2>Întrebări frecvente</h2><h3>Ce face acest transfer cu adevărat „VIP”?</h3><p>Trei lucruri: vehiculul este cel mai nou Mercedes Vito din flota noastră, șoferul îți este alocat exclusiv din momentul aterizării până la destinație (fără opriri comune), iar întâmpinarea ta are prioritate, în față în holul de sosiri, nu într-o zonă generală de așteptare.</p><h3>Un transfer VIP costă mai mult decât un transfer privat standard?</h3><p>Nu. La TORVIAN, VIP este nivelul nostru standard de serviciu, nu un upgrade plătit — fiecare rezervare include deja vehiculul privat, întâmpinarea și urmărirea zborului descrise aici, la același preț fix pe care îl vezi la finalizarea comenzii.</p><h3>Pot cere un șofer vorbitor de engleză sau germană?</h3><p>Da. Toți șoferii vorbesc engleză de bază. Dacă vrei anume un șofer vorbitor de germană sau rusă, menționează la rezervare — confirmăm disponibilitatea înainte de ora preluării.</p><h3>Ce vehicul se folosește pentru serviciul VIP?</h3><p>Un Mercedes Vito cu scaune din piele, aer condiționat și Wi-Fi gratuit, cu loc pentru până la 5 pasageri și spațiu generos pentru bagaje. Este același model în toată flota noastră — rezervările VIP primesc cel mai nou vehicul disponibil la data călătoriei tale.</p><h3>Transferul VIP acoperă orice zonă de stațiune sau doar anumite hoteluri?</h3><p>Orice zonă de stațiune de pe Riviera Turcească pe care o deservim — de la Kundu-Lara, cea mai apropiată de aeroport, până la Alanya, la capătul estic al coastei. Alege destinația la rezervare; același standard VIP se aplică indiferent de distanță.</p>', 'Transfer VIP Aeroportul Antalya | Vehicul privat premium', 'Transfer VIP de la Aeroportul Antalya: cel mai nou Mercedes Vito din flotă, șofer doar pentru tine, întâmpinare prioritară. Preț fix, fără opriri comune. Rezervă online în 2 minute.'
